class Solution {
public:
    int minCost(string colors, vector<int>& neededTime) {
        int res = 0, maxi = 0;
        for (int i = 0; i < colors.size(); i++) {
            if (i > 0 && colors[i] != colors[i - 1]) {
                maxi = 0;
            }
            res += min(maxi, neededTime[i]);
            maxi = max(maxi, neededTime[i]);
        }
        return res;
    }
};
